<script setup lang="ts">
import { Play, Power } from 'lucide-vue-next';
const props=defineProps<{connected:boolean;ready:boolean;controlled:boolean;idle:boolean;mode:'current'|'velocity'|'open';setpoint:number;openVoltage:number}>();
const emit=defineEmits<{ 'update:mode':[value:'current'|'velocity'|'open'];'update:setpoint':[value:number];'update:openVoltage':[value:number];target:[];enable:[];disable:[] }>();
</script>
<template><div class="bottom-actions"><select :value="mode" aria-label="控制模式" :disabled="!connected||!controlled" @change="emit('update:mode',($event.target as HTMLSelectElement).value as typeof mode)"><option value="current">电流控制</option><option value="velocity">速度控制</option><option value="open">开环</option></select><input type="number" step="any" :value="setpoint" :aria-label="mode==='current'?'Iq 目标电流 A':mode==='velocity'?'目标机械速度 rad/s':'目标电角速度 rad/s'" :disabled="!connected||!controlled" @input="emit('update:setpoint',Number(($event.target as HTMLInputElement).value))"><input v-if="mode==='open'" type="number" step="any" :value="openVoltage" aria-label="开环电压 V" :disabled="!connected||!controlled" @input="emit('update:openVoltage',Number(($event.target as HTMLInputElement).value))"><button class="soft-button" :disabled="!connected||!controlled" @click="emit('target')">应用目标</button><button class="secondary" :disabled="!connected" @click="emit('disable')"><Power :size="16"/>停用</button><button class="primary" :disabled="!connected||!ready||!controlled||!idle" @click="emit('enable')"><Play :size="16"/>确认使能</button></div></template>
